    // Update condition to handle 0 value for he_so_chuyen_doi
    if (row.ty_le_chi_tieu_ict_tieu_dung_trung_gian && row.grdp_uoc_tinh && frm.doc.he_so_chuyen_doi !== undefined) {
        let va_ict = row.grdp_uoc_tinh * row.ty_le_chi_tieu_ict_tieu_dung_trung_gian * frm.doc.he_so_chuyen_doi;
        frappe.model.set_value(cdt, cdn, "va_ict", va_ict).then(() => {
            calculate_total_va_ict(frm);
        });
    } else {
        frappe.model.set_value(cdt, cdn, "va_ict", 0).then(() => {
            calculate_total_va_ict(frm);
        });
    }
}

function calculate_total_va_ict(frm) {
    let tong_va_ict = (frm.doc.bang_va_ict || []).reduce((total, row) => {
        return total + (row.va_ict || 0);
    }, 0);
    
    if (frm.doc.tong_va !== tong_va_ict) {
        frm.set_value("tong_va", tong_va_ict);
    }
}

frappe.ui.form.on('VA ICT', {
    bien_dau_vao: function(frm) {
        if (frm.doc.bien_dau_vao) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: "Input Variable",
                    filters: {
                        name: frm.doc.bien_dau_vao
                    }
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('he_so_chuyen_doi', r.message.he_so_chuyen_doi);
                        let input_template_table = r.message.input_template_table || [];
                        // Iterate over the bang_va_ict table in VA ICT and match nganh_kinh_te
                        frm.doc.bang_va_ict.forEach(row => {
                            let matching_input = input_template_table.find(input_row => input_row.nganh_kinh_te === row.nganh_kinh_te);
                            if (matching_input) {
                                // Set the ty_le_chi_tieu_ict_tieu_dung_trung_gian from input_template_table to bang_va_ict
                                frappe.model.set_value(row.doctype, row.name, 'ty_le_chi_tieu_ict_tieu_dung_trung_gian', matching_input.ty_le_chi_tieu_ict_tieu_dung_trung_gian);
                            }
                        });
                        // Refresh the child table to reflect the changes
                        frm.refresh_field('bang_va_ict');
                    }
                }
            })
		}
	}
})

